-- =============================================================================
-- Dalaran Underbelly -- gameobjects (71 spawns, 35 templates)
-- =============================================================================
-- Companion to the GameObjectDisplayInfo additions (101300+) and the 15
-- freshly baked models deployed into patch-8. Five of the twenty retail displays
-- were already shipped here and are reused as-is.
--
-- Coordinates use the same fitted map-1220 -> map-1413 transform as the rest of
-- the city. Gameobjects also store a ROTATION QUATERNION, which is rotated by the
-- transform's yaw (-141.029 deg) as well - otherwise every chair,
-- bench and chest would sit at the right spot facing the wrong way.
--
-- Only Data0/Data1 are carried over, and only for chairs (seat count / height).
-- The retail row has 33 Data fields whose meaning past the first two has drifted
-- from 3.3.5, and a wrong lock or loot id is worse than a blank one.
--
-- APPLY ORDER: deploy the client batch first (models + GameObjectDisplayInfo),
-- then this SQL, then restart the worldserver.
-- Spawn INSERTs are position-guarded and cannot duplicate.
-- =============================================================================

DELETE FROM `gameobject_template` WHERE `entry` BETWEEN 4101800 AND 4101835;

DELETE FROM `gameobject` WHERE `guid` BETWEEN 16400000 AND 16400071;
